def algorithm(func, dim, lb, ub, budget, rng):
    def func_wrapper(x):
        return np.sum(np.square(x))

    x = np.array([np.random.uniform(lb, ub) for _ in range(dim)])
    best_x = x.copy()
    best_func_value = func_wrapper(best_x)

    T = 1.0
    alpha = 0.99

    for i in range(budget):
        new_x = x + rng.uniform(0, 1, dim) * (ub - lb)
        new_x = np.clip(new_x, lb, ub)

        new_func_value = func_wrapper(new_x)

        if new_func_value < best_func_value:
            best_x = new_x.copy()
            best_func_value = new_func_value

        delta = new_func_value - best_func_value
        T *= alpha

        if delta < 0 or np.random.rand() < np.exp(-delta / T):
            x = new_x.copy()

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def sample():
        return rng.uniform(lb, ub, size=dim)

    x_best = clip(sample())
    f_best = func(x_best)
    for _ in range(budget - 1):
        x_candidate = clip(sample())
        f_candidate = func(x_candidate)
        if f_candidate < f_best:
            x_best = x_candidate
            f_best = f_candidate
    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def generate(parents, sigma):
        children = parents + rng.normal(size=(len(parents), dim)) * sigma
        children = clip(children)
        return children

    best_solution = rng.uniform(low=lb, high=ub, size=dim)
    best_fitness = func(best_solution)

    for _ in range(budget):
        new_solutions = generate([best_solution], 0.1)
        fitnesses = [func(s) for s in new_solutions]

        idx = np.argmin(fitnesses)
        if fitnesses[idx] < best_fitness:
            best_solution = new_solutions[idx]
            best_fitness = fitnesses[idx]

    return best_solution

def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(-5, 5, size=dim)
    best_x = x.copy()
    best_y = func(x)

    for _ in range(budget):
        y = func(best_x)
        candidates = [best_x]

        for i in range(dim):
            candidate = best_x.copy()
            if rng.random() < 0.5:
                if rng.random() < 0.5:
                    delta = np.exp(rng.normal(0, 1)) * (ub - lb) / 2
                    candidate[i] += rng.uniform(-delta, delta)
                else:
                    candidate[i] = np.clip(best_x[i] + rng.uniform(lb, ub), lb, ub)
            else:
                if rng.random() < 0.5:
                    candidate[i] = rng.uniform(lb, ub)
                else:
                    candidate[i] = best_x[i]

            candidates.append(candidate)

        candidates = [c for c in candidates if np.all(c >= lb) and np.all(c <= ub)]

        if len(candidates) > 1:
            scores = [func(c) for c in candidates]
            idx = np.argmin(scores)
            candidate = candidates[idx]
            best_x = candidate
            best_y = func(best_x)

    return best_x
